package com.jjm.oficina.servicio;
import com.jjm.oficina.modelo.*;
import com.jjm.oficina.repositorio.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.SimpleTransactionStatus;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class Reconocimiento310HorasTest {
    final UsuarioRepository usuarios=mock(UsuarioRepository.class);final MiembroEquipoRepository miembros=mock(MiembroEquipoRepository.class);final RegistroHorasRepository registros=mock(RegistroHorasRepository.class);final JornadaAutomaticaRepository jornadas=mock(JornadaAutomaticaRepository.class);final JdbcTemplate jdbc=mock(JdbcTemplate.class);final BitacoraService bitacora=mock(BitacoraService.class);final List<RegistroHoras> lista=new ArrayList<>();Usuario u;String periodo="Septiembre - Diciembre";boolean aplicado=false;ReconocimientoHoras2026Service s;
    @BeforeEach void preparar(){u=new Usuario();u.setId(7);u.setEstado("Activo");u.setNombre("Alumno");Rol r=new Rol();r.setNombre("Colaborador");u.setRol(r);MiembroEquipo m=new MiembroEquipo();m.setId(42);m.setUsuario(u);m.setEstado("Activo");when(usuarios.buscarParaAsistencia(7)).thenReturn(Optional.of(u));when(miembros.buscarParaRegularizacion(7)).thenReturn(Optional.of(m));when(registros.buscarParaRegularizacion(eq(42),any(),any())).thenAnswer(i->new ArrayList<>(lista));when(jdbc.queryForList(anyString(),any(Object[].class))).thenAnswer(i->{String sql=i.getArgument(0);if(sql.contains("pmo_reconocimiento2026"))return aplicado?List.of(Map.of("id_usuario",7)):List.of();return List.of(Map.of("rol","Colaborador","periodo",periodo,"inicio","2026-09-01"));});when(jdbc.update(contains("INSERT INTO pmo_reconocimiento2026"),any(Object[].class))).thenAnswer(i->{aplicado=true;return 1;});when(registros.saveAndFlush(any())).thenAnswer(i->{RegistroHoras h=i.getArgument(0);h.setId(lista.size()+1);lista.add(h);return h;});when(registros.save(any())).thenAnswer(i->i.getArgument(0));PlatformTransactionManager gestor=mock(PlatformTransactionManager.class);when(gestor.getTransaction(any())).thenReturn(new SimpleTransactionStatus());s=new ReconocimientoHoras2026Service(usuarios,miembros,registros,jornadas,jdbc,Clock.fixed(Instant.parse("2026-10-14T00:00:00Z"),ZoneOffset.UTC),gestor,bitacora);}
    @Test void nuevaCuentaDelPeriodoTiene31Dias310HorasAprobadasSinEntradasInventadas(){s.reconocer(7);assertEquals(31,lista.size());assertEquals(new BigDecimal("310"),lista.stream().map(RegistroHoras::getHorasTrabajadas).reduce(BigDecimal.ZERO,BigDecimal::add));assertTrue(lista.stream().allMatch(r->"Aprobado".equals(r.getEstadoValidacion())&&r.getHoraEntrada()==null&&r.getDescripcion().contains("administrativo")));assertEquals(LocalDate.of(2026,10,13),lista.getLast().getFecha());}
    @Test void segundaEjecucionYAltaPosteriorNoDuplican(){s.reconocer(7);s.reconocer(7);assertEquals(31,lista.size());verify(bitacora,times(1)).registrar(isNull(),eq("HORAS"),eq("RECONOCIMIENTO_310H_2026"),eq("Usuarios"),eq(7),anyString(),isNull(),eq("310"));}
    @Test void conserva300PreviasYSoloCompleta13DeOctubre(){for(LocalDate dia:RegularizacionHorasService.dias()){RegistroHoras h=new RegistroHoras();h.setFecha(dia);h.setHorasTrabajadas(BigDecimal.TEN);h.setEstadoValidacion("Aprobado");h.setDescripcion(RegularizacionHorasService.ORIGEN);lista.add(h);}s.reconocer(7);assertEquals(31,lista.size());verify(registros,times(1)).saveAndFlush(any());assertEquals(RegularizacionHorasService.ORIGEN,lista.getFirst().getDescripcion());}
    @Test void completaFaltanteDeHoySinReescribirDuracionAnterior(){RegistroHoras h=new RegistroHoras();h.setFecha(LocalDate.of(2026,10,13));h.setHorasTrabajadas(new BigDecimal("5.50"));h.setEstadoValidacion("Pendiente");lista.add(h);s.reconocer(7);assertEquals(new BigDecimal("5.50"),h.getHorasTrabajadas());assertEquals("Aprobado",h.getEstadoValidacion());assertEquals(new BigDecimal("10.00"),lista.stream().filter(r->r.getFecha().equals(h.getFecha())).map(RegistroHoras::getHorasTrabajadas).reduce(BigDecimal.ZERO,BigDecimal::add));}
    @Test void otroPeriodoYProfesorNoRecibenReconocimiento(){periodo="Mayo - Agosto";s.reconocer(7);assertTrue(lista.isEmpty());periodo="Septiembre - Diciembre";u.getRol().setNombre("Superadministrador");s.reconocer(7);assertTrue(lista.isEmpty());}
}
